<?php

declare(strict_types=1);

namespace App\Tools\IcmsCalculator\Domain\Services; use App\Core\Money\Money; use App\Core\Money\Percentage; use App\Core\Tools\Calculation\Data\CalculationMemory; use App\Core\Tools\Calculation\Data\CalculationMemoryStep; use App\Core\Tools\Calculation\Data\ToolCalculationResult; use App\Core\Tools\Calculation\Data\ToolCalculationSummaryItem; use App\Core\Tools\Calculation\Data\ToolCalculationWarning; use App\Core\Tools\Calculation\Enums\ToolCalculationWarningLevel; use App\Core\Tools\Contracts\ToolCalculationInput; use App\Core\Tools\Contracts\ToolCalculator; use App\Tools\IcmsCalculator\Application\Data\CalculationInput; use InvalidArgumentException; final class Calculator implements ToolCalculator { public function calculate(ToolCalculationInput $input):ToolCalculationResult{if(!$input instanceof CalculationInput)throw new InvalidArgumentException('Entrada inválida.');$value=Money::fromDecimal($input->value);$rate=Percentage::fromString($input->rate);$red=Percentage::fromString($input->reduction?:'0');$scale=100000000;$effective=intdiv($rate->millionthsOfPercent()*($scale-$red->millionthsOfPercent()),$scale);if($effective>=$scale)throw new InvalidArgumentException('Alíquota efetiva inválida.');if($input->valueExcludesIcms){$grossMinor=intdiv($value->minorAmount()*$scale + intdiv($scale-$effective,2),$scale-$effective);$gross=Money::fromMinor($grossMinor);$tax=Money::fromMinor($grossMinor-$value->minorAmount());$base=Money::fromMinor(intdiv($grossMinor*($scale-$red->millionthsOfPercent())+$scale/2,$scale));}else{$gross=$value;$base=Money::fromMinor(intdiv($value->minorAmount()*($scale-$red->millionthsOfPercent())+$scale/2,$scale));$tax=$base->percentage($rate);} $memory=new CalculationMemory('1.0.0',[new CalculationMemoryStep('base','Base tributável','valor da operação ajustado pela redução de base informada',['rate'=>$rate->toDecimalString(),'reduction'=>$red->toDecimalString()],$base->minorAmount()),new CalculationMemoryStep('icms','ICMS próprio','base tributável × alíquota informada',['rate'=>$rate->toDecimalString()],$tax->minorAmount())],[],['A alíquota e a composição da base devem ser confirmadas na legislação da UF e no enquadramento da operação.','A ferramenta não calcula ST, DIFAL, FCP, benefícios, créditos ou débitos de apuração.'],true);return new ToolCalculationResult('calculadora-icms-proprio','1.0.0',[new ToolCalculationSummaryItem('base','Base de cálculo',$base->formatPtBr()),new ToolCalculationSummaryItem('icms','ICMS próprio',$tax->formatPtBr()),new ToolCalculationSummaryItem('total','Valor com ICMS',$gross->formatPtBr())],['rate'=>$rate->toDecimalString(),'reduction'=>$red->toDecimalString(),'value_excludes_icms'=>$input->valueExcludesIcms,'official_source'=>'Lei Complementar 87/1996, art. 13; parâmetros estaduais devem ser confirmados'],[new ToolCalculationWarning('parametric','Cálculo paramétrico: não presume alíquota, benefício, isenção, diferimento, crédito presumido ou composição específica de base.',ToolCalculationWarningLevel::Info)],calculationMemory:$memory);}}
